import itertools
import json

def solve():
    houses = list(range(6))  # indices 0..5 represent houses 1..6
    names = ["Arnold", "Eric", "Peter", "Alice", "Carol", "Bob"]
    musics = ["jazz", "pop", "classical", "rock", "hip hop", "country"]

    solutions = []

    for name_perm in itertools.permutations(names):
        # Clue 3: Carol is in the sixth house (index 5)
        if name_perm[5] != "Carol":
            continue

        # From Clue 9 and 4: Hip-hop is in the third house => Eric must be at house 2 (index 1)
        if name_perm[1] != "Eric":
            continue

        # Clue 6: Arnold is not in the fifth house (index 4)
        if name_perm[4] == "Arnold":
            continue

        pos_name = {n: name_perm.index(n) for n in names}

        # Clue 10: There is one house between Peter and Bob
        if abs(pos_name["Peter"] - pos_name["Bob"]) != 2:
            continue

        # Clue 7 and 8 together: Pop is Peter, Arnold is somewhere to the right of pop (Peter)
        if pos_name["Arnold"] <= pos_name["Peter"]:
            continue

        # Prepare music assignment
        # Initialize music array per house with None
        music_arr = [None] * 6

        # Clue 9: hip hop at third house (index 2)
        music_arr[2] = "hip hop"

        # Clue 5: Carol is country
        music_arr[5] = "country"

        # Clue 8: Pop is Peter
        peter_pos = pos_name["Peter"]
        # If pop conflicts with already assigned hip hop or country, skip
        if music_arr[peter_pos] is not None and music_arr[peter_pos] != "pop":
            continue
        music_arr[peter_pos] = "pop"

        # Remaining musics to place
        assigned = {m for m in music_arr if m is not None}
        remaining_musics = [m for m in musics if m not in assigned]
        remaining_positions = [i for i in houses if music_arr[i] is None]

        for music_perm in itertools.permutations(remaining_musics):
            temp_music = music_arr[:]
            for idx, m in zip(remaining_positions, music_perm):
                temp_music[idx] = m

            pos_music = {m: temp_music.index(m) for m in musics}

            # Clue 11: Rock not in the fifth house (index 4)
            if pos_music["rock"] == 4:
                continue

            # Clue 1: Bob is directly left of the person who loves jazz
            if pos_name["Bob"] + 1 != pos_music["jazz"]:
                continue

            # Clue 2: Eric is somewhere to the left of the person who loves hip-hop music
            if not (pos_name["Eric"] < pos_music["hip hop"]):
                continue

            # Clue 4: Eric and the person who loves hip-hop are next to each other
            if abs(pos_name["Eric"] - pos_music["hip hop"]) != 1:
                continue

            # All constraints satisfied; record solution
            solution_rows = []
            for i in range(6):
                house_number = str(i + 1)
                solution_rows.append([house_number, name_perm[i], temp_music[i]])

            solutions.append({
                "solution": {
                    "header": ["House", "Name", "favorite music genres"],
                    "rows": solution_rows
                }
            })

    # Assuming unique solution; output the first one
    if not solutions:
        raise RuntimeError("No solution found.")
    print(json.dumps(solutions[0], ensure_ascii=False))

if __name__ == "__main__":
    solve()
